            XCTAssertGreaterThanOrEqual(button.frame.height + 0.000001, 44)
            button.coordinate(withNormalizedOffset: .zero).withOffset(CGVector(dx: button.frame.width - 4, dy: 4)).tap()
        }
        openProjects()
