    func testBoardPickerSearchNormal() { boardPickerSearch(paging: true, library: "91c4c2c2-5336-49ea-a239-d61598f0607e") }
    func testBoardPickerSearchLargestText() { boardPickerSearch(library: "ed788ee8-1487-4130-ad4e-827d3cae93ca") }

    private func boardPickerSearch(paging: Bool = false, library: String) {
        let app = XCUIApplication(); app.launchArguments = ["--native-ui-test-library", library]; app.launch()
        boardEnabled(app.buttons["tab-menu"], timeout: 30); boardOpen(app)
        boardTap(app, "board-filter-open"); boardTap(app, "board-picker-tokens")
        let query = app.textFields["board-picker-search"]
        func search(_ text: String, submit: Bool = true) {
            boardEnabled(query); XCTAssertGreaterThanOrEqual(query.frame.height, 44 - 0.001)
            query.tap()
            let value = query.value as? String ?? ""
            if !value.isEmpty && value != query.placeholderValue {
                query.press(forDuration: 1)
                let selectAll = app.descendants(matching: .any)["Select All"].firstMatch
                for _ in 0..<3 {
                    if selectAll.waitForExistence(timeout: 1), selectAll.isHittable { break }
                    let next = app.buttons["Next Page"]
                    guard next.exists else { break }
                    next.tap()
                }
                if selectAll.exists { selectAll.tap() }
                else {
                    // A long single word may already be fully selected by the press.
                    XCTAssertTrue(app.menuItems["Cut"].exists || app.buttons["Cut"].exists)
                }
                query.typeText(XCUIKeyboardKey.delete.rawValue)
            }
            XCTAssertTrue((query.value as? String ?? "").isEmpty || query.value as? String == query.placeholderValue)
            query.typeText(text + (submit ? "\n" : ""))
        }
        func projects() {
            let button = app.buttons["board-picker-projects"]
            boardEnabled(button); XCTAssertTrue(button.isHittable)
            button.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5)).tap()
            boardEnabled(query)
        }
        func option(_ id: String) -> XCUIElement {
            let row = app.buttons[id]
            revealPagedElement(app, row, in: app.scrollViews["board-filter-scroll"])
            boardEnabled(row); XCTAssertGreaterThanOrEqual(row.frame.height, 44 - 0.001); return row
        }
        search("  TASK78-102  ")
        let token = option("board-filter-token-@task78-102")
        XCTAssertFalse(app.buttons["board-filter-token-@task78-000"].exists)
        token.tap(); boardEnabled(token); XCTAssertTrue(token.isSelected)
        token.tap(); boardEnabled(token); XCTAssertEqual(token.value as? String, "Excluded")
        token.tap(); boardEnabled(token); XCTAssertFalse(token.isSelected); XCTAssertEqual(token.value as? String, "0")
        search("no-such-task78-option")
        XCTAssertTrue(app.staticTexts["board-picker-empty"].waitForExistence(timeout: 10))
        if paging {
            search("task78-")
            let more = app.buttons["board-more-tokens"]
            revealPagedElement(app, more, in: app.scrollViews["board-filter-scroll"])
            boardTap(app, "board-more-tokens")
            _ = option("board-filter-token-@task78-102")
            XCTAssertFalse(app.buttons["board-more-tokens"].exists)
        }
        search("task78-10"); _ = option("board-filter-token-@task78-102")
        XCTAssertFalse(app.buttons["board-more-tokens"].exists)
        boardTap(app, "board-picker-back"); projects()
        boardEnabled(query)
        XCTAssertEqual(query.value as? String, query.placeholderValue)
        search("  TASK78 PROJECT 102  ")
        let project = option("board-filter-project-task78-project-102")
        XCTAssertFalse(app.buttons["board-filter-project-task78-project-000"].exists)
        project.tap(); boardEnabled(project); XCTAssertTrue(project.isSelected)
        search(String(repeating: "x", count: 501), submit: false)
        XCTAssertTrue(app.staticTexts["board-error"].waitForExistence(timeout: 10))
        // Correct the rejected query while its caret is still at the end.
        query.typeText(String(repeating: XCUIKeyboardKey.delete.rawValue, count: 501) + "task78 project 102\n"); boardEnabled(project); XCTAssertTrue(project.isSelected)
        let shot = XCTAttachment(screenshot: app.screenshot()); shot.name = "Board searched Project picker"; shot.lifetime = .keepAlways; add(shot)
        boardTap(app, "board-filter-close"); boardEnabled(app.buttons["board-filter-open"])
        XCTAssertEqual(app.staticTexts["board-count-next"].label, "1")
        boardTap(app, "search-open"); boardTap(app, "search-close"); boardEnabled(app.buttons["board-filter-open"])
        XCTAssertEqual(app.staticTexts["board-count-next"].label, "1")
        boardTap(app, "board-filter-open"); projects()
        boardEnabled(query)
        XCTAssertEqual(query.value as? String, query.placeholderValue)
        search("task78 project 102"); XCTAssertTrue(option("board-filter-project-task78-project-102").isSelected)
        boardTap(app, "board-filter-clear"); boardEnabled(app.buttons["board-filter-clear"])
        boardTap(app, "board-filter-close"); boardEnabled(app.buttons["board-filter-open"])
        app.terminate(); app.launch(); boardEnabled(app.buttons["tab-menu"], timeout: 30); boardOpen(app)
        boardTap(app, "board-filter-open"); boardTap(app, "board-picker-tokens")
        boardEnabled(query)
        XCTAssertEqual(query.value as? String, query.placeholderValue)
        search("task78-102"); XCTAssertFalse(option("board-filter-token-@task78-102").isSelected)
        boardTap(app, "board-filter-close"); app.terminate()
    }

    func testDeferredProjectActivationNormal() { deferredProjectActivation(library: "a54438a9-d7f7-4931-b30b-7b8c61a4be93") }
    func testDeferredProjectActivationLargestText() { deferredProjectActivation(library: "2381a180-a4ed-4e48-8d73-4fbb22e2995f") }

    private func deferredProjectOpen(_ app: XCUIApplication, _ view: String) {
        for surface in ["waiting", "someday"] where app.buttons[surface + "-back"].exists {
            boardTap(app, surface + "-back")
        }
        boardEnabled(app.buttons["tab-menu"], timeout: 30); boardTap(app, "tab-menu")
        let item = app.buttons["menu-" + view]
        if !item.isHittable { revealPagedElement(app, item, in: app.scrollViews.containing(.button, identifier: "menu-projects").firstMatch) }
        boardTap(app, "menu-" + view); boardEnabled(app.buttons[view + "-projects-toggle"])
    }

    private func deferredProjectRow(_ app: XCUIApplication, _ view: String, _ suffix: String) -> XCUIElement {
        let row = app.buttons[view + "-project-task77-" + view + "-" + suffix]
        revealPagedElement(app, row, in: app.scrollViews[view + "-scroll"])
        boardEnabled(row); XCTAssertGreaterThanOrEqual(row.frame.height, 44 - 0.001)
        return row
    }

    private func deferredProjectSwipe(_ row: XCUIElement) {
        row.coordinate(withNormalizedOffset: CGVector(dx: 0.2, dy: 0.5)).press(forDuration: 0.05,
            thenDragTo: row.coordinate(withNormalizedOffset: CGVector(dx: 0.8, dy: 0.5)))
    }

    private func deferredProjectActivation(library: String) {
        let app = XCUIApplication(); app.launchArguments = ["--native-ui-test-library", library]; app.launch()
        for view in ["waiting", "someday"] {
            deferredProjectOpen(app, view)
            let row = deferredProjectRow(app, view, "a")
            row.tap(); boardEnabled(app.buttons["project-back"]); boardTap(app, "project-back")
            _ = deferredProjectRow(app, view, "a")
            let short = row.coordinate(withNormalizedOffset: CGVector(dx: 0.3, dy: 0.5))
            short.press(forDuration: 0.05, thenDragTo: short.withOffset(CGVector(dx: 45, dy: 0)))
            XCTAssertFalse(app.buttons["project-back"].exists); XCTAssertTrue(row.exists)
            let start = row.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.8))
            start.press(forDuration: 0.05, thenDragTo: start.withOffset(CGVector(dx: 0, dy: -80)))
            XCTAssertFalse(app.buttons["project-back"].exists); XCTAssertTrue(row.exists)
            _ = deferredProjectRow(app, view, "a"); deferredProjectSwipe(row)
            expectation(for: NSPredicate(format: "exists == false"), evaluatedWith: row); waitForExpectations(timeout: 15)
            _ = deferredProjectRow(app, view, "b")
            boardTap(app, "search-open"); boardEnabled(app.buttons["search-close"]); boardTap(app, "search-close")
            _ = deferredProjectRow(app, view, "b"); XCTAssertFalse(row.exists)
        }
        app.terminate(); app.launch()
        for view in ["waiting", "someday"] {
            deferredProjectOpen(app, view); _ = deferredProjectRow(app, view, "b")
            XCTAssertFalse(app.buttons[view + "-project-task77-" + view + "-a"].exists)
        }
        let shot = XCTAttachment(screenshot: app.screenshot()); shot.name = "Deferred Projects after Reactivate and restart"; shot.lifetime = .keepAlways; add(shot)
        app.terminate()
    }

    func testDeferredProjectActivationSaveFailure() {
        let app = XCUIApplication(); app.launchArguments = ["--native-ui-test-library", "c1b10fcd-6750-4a9b-9b60-41471ce9d5c4"]; app.launch()
        deferredProjectOpen(app, "waiting"); deferredProjectSwipe(deferredProjectRow(app, "waiting", "a"))
        let failure = app.staticTexts["persistence-error"]
        XCTAssertTrue(failure.waitForExistence(timeout: 15)); boardEnabled(app.buttons["persistence-retry"])
        XCTAssertFalse(app.buttons["waiting-back"].isEnabled)
        for _ in 0..<2 {
            boardTap(app, "persistence-retry"); boardEnabled(app.buttons["persistence-retry"])
            XCTAssertTrue(failure.exists); XCTAssertFalse(app.buttons["waiting-project-task77-waiting-a"].isEnabled)
        }
        let shot = XCTAttachment(screenshot: app.screenshot()); shot.name = "Deferred Reactivate keeps exact retry"; shot.lifetime = .keepAlways; add(shot)
        app.terminate()
    }

    func testDeferredProjectActivationColdRecovery() {
        let app = XCUIApplication(); app.launchArguments = ["--native-ui-test-library", "c1b10fcd-6750-4a9b-9b60-41471ce9d5c4"]; app.launch()
        deferredProjectOpen(app, "waiting"); _ = deferredProjectRow(app, "waiting", "b")
        XCTAssertFalse(app.buttons["waiting-project-task77-waiting-a"].exists)
        XCTAssertFalse(app.staticTexts["persistence-error"].exists)
        deferredProjectOpen(app, "someday"); let row = deferredProjectRow(app, "someday", "a"); deferredProjectSwipe(row)
        expectation(for: NSPredicate(format: "exists == false"), evaluatedWith: row); waitForExpectations(timeout: 15)
        _ = deferredProjectRow(app, "someday", "b")
        app.terminate(); app.launch(); deferredProjectOpen(app, "someday")
        _ = deferredProjectRow(app, "someday", "b"); XCTAssertFalse(row.exists); app.terminate()
    }

    func testHistoryViewRestorationNormal() { historyViewRestoration(library: "a575dfe8-784f-48df-87a9-73428aa65776", largest: false) }
    func testHistoryViewRestorationLargestText() { historyViewRestoration(library: "39061af8-bbc8-4667-9b93-014fcedbf476", largest: true) }

    private func historyViewOpen(_ app: XCUIApplication, tab: String = "done") {
        boardEnabled(app.buttons["tab-menu"], timeout: 30); boardTap(app, "tab-menu")
        let history = app.buttons["menu-history"]
        if !history.isHittable { revealPagedElement(app, history, in: app.scrollViews.containing(.button, identifier: "menu-projects").firstMatch) }
        boardTap(app, "menu-history"); boardEnabled(app.buttons["history-tab-done"])
        historyViewTab(app, tab)
    }

    private func historyViewTab(_ app: XCUIApplication, _ tab: String) {
        if !app.buttons["history-tab-" + tab].isSelected { boardTap(app, "history-tab-" + tab) }
        boardEnabled(app.buttons[tab + "-overflow-button"])
    }

    private func historyViewTap(_ app: XCUIApplication, _ tab: String, _ id: String) {
        let button = app.buttons[id]
        if !button.isHittable, app.scrollViews[tab + "-panel-scroll"].exists {
            revealPagedElement(app, button, in: app.scrollViews[tab + "-panel-scroll"])
        }
        boardEnabled(button); XCTAssertTrue(button.isHittable)
        XCTAssertGreaterThanOrEqual(button.frame.height, 44 - 0.001); button.tap()
    }

    private func historyViewChoice(_ app: XCUIApplication, _ tab: String, _ field: String, _ value: String, selected: Bool = false, failed: Bool = false) {
        boardTap(app, tab + "-overflow-button"); boardTap(app, tab + "-" + field + "-action")
        let id = tab + "-" + field + "-" + value
        if selected {
            let choice = app.buttons[id]
            if !choice.isHittable, app.scrollViews[tab + "-panel-scroll"].exists {
                revealPagedElement(app, choice, in: app.scrollViews[tab + "-panel-scroll"])
            }
            XCTAssertTrue(choice.isSelected); historyViewTap(app, tab, tab + "-menu-close")
        } else { historyViewTap(app, tab, id) }
        boardEnabled(app.buttons[failed ? (tab == "done" ? "done-retry" : "archive-retry") : tab + "-overflow-button"])
    }

    private func historyViewFold(_ app: XCUIApplication, _ tab: String, _ id: String, open: Bool, toggle: Bool = false) {
        let prefix = tab == "done" ? "done" : "archive"
        let identifier = prefix + "-section-" + id
        let matches = app.buttons.matching(identifier: identifier)
        let button = matches.allElementsBoundByIndex.first { $0.identifier.utf8.elementsEqual(identifier.utf8) } ?? matches.firstMatch
        revealPagedElement(app, button, in: app.scrollViews[prefix + "-scroll"])
        boardEnabled(button); XCTAssertEqual(button.value as? String, open ? "Collapse" : "Expand")
        XCTAssertGreaterThanOrEqual(button.frame.height, 44 - 0.001)
        if toggle { button.tap(); boardEnabled(app.buttons[tab + "-overflow-button"]) }
    }

    private func historyViewRestoration(library: String, largest: Bool) {
        let app = XCUIApplication(); app.launchArguments = ["--native-ui-test-library", library]
        app.launch(); historyViewOpen(app)
        for tab in ["done", "archived"] {
            historyViewTab(app, tab)
            historyViewChoice(app, tab, "group", "area")
            historyViewFold(app, tab, "task76-area-a", open: true, toggle: true)
            historyViewChoice(app, tab, "group", "tag")
            historyViewFold(app, tab, "tag:Task76 B", open: true, toggle: true)
            historyViewChoice(app, tab, "group", "area")
            historyViewFold(app, tab, "task76-area-a", open: false)
            historyViewChoice(app, tab, "sort", tab == "done" ? "title" : "created-desc")
        }
        historyViewTab(app, "done"); boardTap(app, "search-open"); boardEnabled(app.textFields["search-input"])
        boardTap(app, "search-close"); historyViewFold(app, "done", "task76-area-a", open: false)
        let task = app.buttons["task-title-task76-done-b"]
        revealPagedElement(app, task, in: app.scrollViews["done-scroll"]); task.tap()
        boardEnabled(app.buttons["task-view-close"]); boardTap(app, "task-view-close")
        historyViewFold(app, "done", "task76-area-a", open: false)
        app.terminate(); app.launch(); historyViewOpen(app)
        for tab in ["done", "archived"] {
            historyViewTab(app, tab)
            historyViewFold(app, tab, "task76-area-a", open: false)
            historyViewChoice(app, tab, "sort", tab == "done" ? "title" : "created-desc", selected: true)
            historyViewChoice(app, tab, "group", "tag")
            historyViewFold(app, tab, "tag:Task76 B", open: false, toggle: !largest)
        }
        if !largest {
            app.terminate(); app.launch(); historyViewOpen(app)
            for tab in ["done", "archived"] {
                historyViewTab(app, tab); historyViewFold(app, tab, "tag:Task76 B", open: true)
                historyViewChoice(app, tab, "group", "area"); historyViewFold(app, tab, "task76-area-a", open: false)
            }
        }
        let shot = XCTAttachment(screenshot: app.screenshot()); shot.name = "History restored independent views"
        shot.lifetime = .keepAlways; add(shot); app.terminate()
    }

    func testHistoryViewReadFailureAndColdRestart() {
        let app = XCUIApplication(); let args = ["--native-ui-test-library", "13bf5201-5cc8-44dc-8cc1-9c90377cd876"]
        for tab in ["done", "archived"] {
            app.launchArguments = args; app.launch(); historyViewOpen(app, tab: tab)
            historyViewChoice(app, tab, "group", "area"); historyViewFold(app, tab, "task76-area-a", open: true, toggle: true)
            app.terminate(); app.launchArguments = args + ["--native-history-view-read-failure"]
            app.launch(); historyViewOpen(app, tab: tab); historyViewChoice(app, tab, "group", "tag", failed: true)
            XCTAssertTrue(app.staticTexts[tab == "done" ? "done-error" : "archive-error"].exists)
            app.terminate(); app.launchArguments = args; app.launch(); historyViewOpen(app, tab: tab)
            historyViewFold(app, tab, "task76-area-a", open: false)
            app.terminate(); app.launchArguments = args + ["--native-history-view-read-failure"]
            app.launch(); historyViewOpen(app, tab: tab); historyViewChoice(app, tab, "group", "tag", failed: true)
            boardTap(app, tab == "done" ? "done-retry" : "archive-retry")
            boardEnabled(app.buttons[tab + "-overflow-button"]); historyViewFold(app, tab, "tag:Task76 B", open: true)
            app.terminate(); app.launchArguments = args; app.launch(); historyViewOpen(app, tab: tab)
            historyViewFold(app, tab, "tag:Task76 B", open: true); app.terminate()
        }
    }

