        shot.lifetime = .keepAlways; add(shot); app.terminate()
    }

    func testReferenceSortColdRecovery() {
        let app = XCUIApplication(); app.launchArguments = ["--native-ui-test-library", "09491429-1569-4dd0-9926-53c7e26f44d8"]
