    private func taskAssignedToEditor(library: String) {
        continueAfterFailure = false
        let app = XCUIApplication(); app.launchArguments = ["--native-ui-test-library", library]; app.launch()
        func openTask(_ id: String, title: String) {
            boardEnabled(app.buttons["search-open"], timeout: 30); boardTap(app, "search-open")
            let query = app.textFields["search-input"]; boardEnabled(query); query.tap(); query.typeText(title)
            boardTap(app, "search-task-" + id); boardTap(app, "task-mode-edit")
            expectation(for: NSPredicate(format: "selected == true"), evaluatedWith: app.buttons["task-mode-edit"])
            waitForExpectations(timeout: 10)
        }
        func reveal(_ element: XCUIElement) {
            boardEnabled(element)
            let scroll = app.scrollViews["task-editor-scroll"]
            for _ in 0..<15 {
                var frame = scroll.frame
                if app.keyboards.firstMatch.exists { frame.size.height = max(0, app.keyboards.firstMatch.frame.minY - frame.minY) }
                if element.exists && element.isHittable && frame.contains(element.frame) { break }
                let above = element.exists && element.frame.minY < frame.minY
                if app.keyboards.firstMatch.exists {
                    let origin = app.coordinate(withNormalizedOffset: .zero)
                    let distance = min(frame.height * 0.5, max(20, abs(element.frame.midY - frame.midY)))
                    let startY = frame.minY + frame.height * (above ? 0.25 : 0.75)
                    let start = origin.withOffset(CGVector(dx: frame.midX, dy: startY))
                    let end = origin.withOffset(CGVector(dx: frame.midX, dy: startY + (above ? distance : -distance)))
                    start.press(forDuration: 0, thenDragTo: end, withVelocity: .slow, thenHoldForDuration: 0.2)
                } else if above { scroll.swipeDown() }
                else { scroll.swipeUp() }
            }
            XCTAssertTrue(element.isHittable)
        }
        func assignment() -> XCUIElement {
            let header = app.buttons["task-editor-section-organization"]
            boardEnabled(header)
            expectation(for: NSPredicate(format: "value IN %@", ["Expand", "Collapse"]), evaluatedWith: header)
            waitForExpectations(timeout: 10)
            if header.value as? String == "Expand" {
                reveal(header); header.tap()
                expectation(for: NSPredicate(format: "value == %@", "Collapse"), evaluatedWith: header)
                waitForExpectations(timeout: 10)
            }
            let input = app.textFields["task-editor-assignedTo"]; reveal(input); return input
        }
        func replaceAssignment(with text: String) {
            let input = assignment(); input.tap()
            boardEnabled(app.keyboards.firstMatch)
            reveal(input)
            // One text-field paragraph: triple-tap selects all without a floating menu.
            input.tap(withNumberOfTaps: 3, numberOfTouches: 1)
            input.typeText(XCUIKeyboardKey.delete.rawValue)
            XCTAssertTrue((input.value as? String ?? "").isEmpty || input.value as? String == input.placeholderValue)
            if !text.isEmpty { input.typeText(text) }
            XCTAssertTrue(input.value as? String == text || (text.isEmpty && input.value as? String == input.placeholderValue))
        }
        func restart() { app.terminate(); app.launch() }
        openTask("task112-waiting", title: "Task112 Waiting")
        let input = assignment(); XCTAssertEqual(input.label, "Assigned To"); XCTAssertFalse((input.placeholderValue ?? "").isEmpty); input.tap(); input.typeText("Person112 A")
        let choice = app.buttons["task-assignedTo-suggestion-Person112 Ada"]
        reveal(choice); choice.tap()
        XCTAssertEqual(input.value as? String, "Person112 Ada")
        XCTAssertTrue(app.keyboards.firstMatch.exists, "Choosing a Person keeps the field focused")
        boardTap(app, "task-editor-save")
        restart(); openTask("task112-waiting", title: "Task112 Waiting")
        XCTAssertEqual(assignment().value as? String, "Person112 Ada")
        replaceAssignment(with: "  Freeform112  ")
        boardTap(app, "task-mode-view")
        XCTAssertTrue(app.staticTexts["Freeform112"].waitForExistence(timeout: 10))
        boardTap(app, "task-mode-edit")
        XCTAssertEqual(assignment().value as? String, "  Freeform112  ")
        boardTap(app, "task-editor-save")
        restart(); openTask("task112-waiting", title: "Task112 Waiting")
        XCTAssertEqual(assignment().value as? String, "Freeform112")
        let shot = XCTAttachment(screenshot: app.screenshot()); shot.name = "Saved Assigned To editor"; shot.lifetime = .keepAlways; add(shot)
        replaceAssignment(with: "Discard112")
        boardTap(app, "task-view-close"); boardTap(app, "task-editor-discard"); boardTap(app, "search-close")
        openTask("task112-waiting", title: "Task112 Waiting")
        XCTAssertEqual(assignment().value as? String, "Freeform112")
        replaceAssignment(with: "")
        boardTap(app, "task-editor-save")
        restart(); openTask("task112-waiting", title: "Task112 Waiting")
        let cleared = assignment(); XCTAssertEqual(cleared.value as? String, cleared.placeholderValue)
        boardTap(app, "task-view-close"); boardTap(app, "search-close")
        // A bounded suggestions query must not truncate a longer free-text assignment.
        openTask("task112-next", title: "Task112 Next")
        let long = String(repeating: "Q", count: 2001)
        let next = assignment(); next.tap(); next.typeText(long)
        boardTap(app, "task-editor-save")
        restart(); openTask("task112-next", title: "Task112 Next")
        XCTAssertEqual(assignment().value as? String, long)
        XCTAssertFalse(app.staticTexts["task-assignedTo-error"].exists)
        boardTap(app, "task-view-close"); boardTap(app, "search-close"); app.terminate()
    }

    func testTaskLocationPresetEditDiscardAndRestart() {
        continueAfterFailure = false
        let app = XCUIApplication()
        let library = UUID().uuidString.lowercased()
        app.launchArguments = ["--native-ui-test-library", library]
        print("Location editor isolated library: " + library)
        app.launch()
        let title = "iOS location " + String(UUID().uuidString.prefix(8))
        boardEnabled(app.buttons["capture-open"], timeout: 30); boardTap(app, "capture-open")
        app.textViews["capture-input"].typeText(title)
        boardTap(app, "capture-save")
        boardEnabled(app.buttons[title], timeout: 30)
        let taskID = String(app.buttons[title].identifier.dropFirst("task-title-".count))
        func openTask() {
            boardTap(app, "search-open")
            let input = app.textFields["search-input"]; boardEnabled(input); input.tap(); input.typeText(title)
            let row = app.buttons["search-task-" + taskID]
            boardEnabled(row, timeout: 30); row.tap(); boardTap(app, "task-mode-edit")
        }
        func closeTask() { boardTap(app, "task-view-close"); boardTap(app, "search-close") }
        var fullFields = false
        func preset(_ value: String) {
            task108Open(app); task109Pick(app, value)
            fullFields = value == "full"
            boardTap(app, "gtd-taskEditor-back"); boardTap(app, "gtd-back"); boardTap(app, "settings-back")
        }
        func disclosureReady(_ control: XCUIElement) {
            boardEnabled(control)
            expectation(for: NSPredicate(format: "value IN %@", ["Expand", "Collapse"]), evaluatedWith: control)
            waitForExpectations(timeout: 10)
        }
        func editReady() {
            expectation(for: NSPredicate(format: "selected == true"), evaluatedWith: app.buttons["task-mode-edit"])
            waitForExpectations(timeout: 10)
            XCTAssertTrue(app.descendants(matching: .any).matching(identifier: "task-editor-title").firstMatch.waitForExistence(timeout: 10))
        }
        func location() -> XCUIElement {
            editReady()
            let scroll = app.scrollViews["task-editor-scroll"]
            for section in fullFields ? ["scheduling", "organization"] : [] {
                let control = app.buttons["task-editor-section-" + section]
                disclosureReady(control)
                if control.value as? String == "Collapse" {
                    revealPagedElement(app, control, in: scroll, outerEdge: true)
                    control.tap()
                    expectation(for: NSPredicate(format: "value == %@", "Expand"), evaluatedWith: control)
                    waitForExpectations(timeout: 10)
                }
            }
            let header = app.buttons["task-editor-section-details"]
            disclosureReady(header)
            revealPagedElement(app, header, in: scroll, outerEdge: true)
            if header.value as? String == "Expand" {
                header.tap()
                expectation(for: NSPredicate(format: "value == %@", "Collapse"), evaluatedWith: header)
                waitForExpectations(timeout: 10)
            }
            let input = app.textFields["task-editor-location"]
            for _ in 0..<12 {
                if input.exists && input.isHittable && scroll.frame.contains(input.frame) { break }
                if input.exists && input.frame.minY < scroll.frame.minY { scroll.swipeDown() }
                else { scroll.swipeUp() }
                XCTAssertEqual(header.value as? String, "Collapse", "Scrolling keeps Details open")
            }
            boardEnabled(input)
            XCTAssertTrue(input.isHittable && scroll.frame.contains(input.frame))
            return input
        }
        preset("simple"); openTask()
        XCTAssertFalse(app.textFields["task-editor-location"].exists)
        closeTask()
        preset("full"); openTask()
        let value = "Library 111"
        let input = location(); input.tap(); input.typeText(value)
        boardTap(app, "task-mode-view")
        revealPagedElement(app, app.staticTexts[value], in: app.scrollViews["task-editor-scroll"])
        boardTap(app, "task-mode-edit")
        editReady()
        for (section, expected) in [("scheduling", "Expand"), ("organization", "Expand"), ("details", "Collapse")] {
            let header = app.buttons["task-editor-section-" + section]
            disclosureReady(header)
            XCTAssertEqual(header.value as? String, expected, "Preview retains the section disclosure state")
        }
        XCTAssertEqual(location().value as? String, value, "Preview refresh retains the unsaved Location")
        boardTap(app, "task-editor-save")
        app.terminate(); app.launch(); boardEnabled(app.buttons["search-open"], timeout: 30)
        openTask(); XCTAssertEqual(location().value as? String, value)
        replaceProjectNotesText(location(), with: "Discard this location")
        boardTap(app, "task-view-close"); boardTap(app, "task-editor-discard"); boardTap(app, "search-close")
        preset("simple"); openTask()
        XCTAssertEqual(location().value as? String, value, "Filled Location remains visible under Simple")
        let shot = XCTAttachment(screenshot: app.screenshot()); shot.name = "Saved Location editor"; shot.lifetime = .keepAlways; add(shot)
        let clearing = location()
        replaceProjectNotesText(clearing, with: "")
        boardTap(app, "task-editor-save")
        app.terminate(); app.launch(); boardEnabled(app.buttons["search-open"], timeout: 30)
        openTask(); XCTAssertFalse(app.textFields["task-editor-location"].exists)
        closeTask(); app.terminate()
    }

    func testTaskMetadataEditPreviewDiscardAndRestart() {
        let app = XCUIApplication()
        let library = UUID().uuidString.lowercased()
        app.launchArguments = ["--native-ui-test-library", library]
        print("Durable editor isolated library: " + library)
        app.launch()
        func enabled(_ element: XCUIElement, timeout: TimeInterval = 10) {
            XCTAssertTrue(element.waitForExistence(timeout: timeout))
            expectation(for: NSPredicate(format: "enabled == true"), evaluatedWith: element)
            waitForExpectations(timeout: timeout)
        }
        func inboxTask(_ title: String) -> XCUIElement {
            XCTAssertTrue(app.staticTexts["inbox-title"].waitForExistence(timeout: 30))
            let row = app.buttons[title]
            for _ in 0..<12 where !row.exists { app.swipeUp() }
            return row
        }
        func tap(_ id: String) {
            let button = app.buttons.matching(identifier: id).firstMatch
            if id.hasPrefix("task-editor-priority-") || id.hasPrefix("task-editor-energyLevel-") || id.hasPrefix("task-editor-section-") {
                revealPagedElement(app, button, in: app.scrollViews["task-editor-scroll"])
            }
            enabled(button)
            button.tap()
        }
        enabled(app.buttons["capture-open"], timeout: 30)
        app.buttons["capture-open"].tap()
        let title = "iOS metadata " + String(UUID().uuidString.prefix(8))
        app.textViews["capture-input"].typeText(title + " /priority:low /energy:low")
        enabled(app.buttons["capture-save"])
        app.buttons["capture-save"].tap()
        enabled(inboxTask(title))
        app.buttons[title].tap()
        tap("task-mode-edit")
        let titleInput = app.descendants(matching: .any).matching(identifier: "task-editor-title").firstMatch
        titleInput.coordinate(withNormalizedOffset: CGVector(dx: 0.98, dy: 0.8)).tap()
        titleInput.typeText(" changed")
        tap("task-mode-view")
        tap("task-mode-edit")
        // Metadata is revealed by its captured value, preserving the default hidden-field preference.
        if !app.buttons["task-editor-priority-urgent"].exists { tap("task-editor-section-organization") }
        tap("task-editor-priority-urgent")
        tap("task-editor-energyLevel-high")
        XCTAssertTrue(app.buttons["task-editor-priority-urgent"].isSelected)
        XCTAssertTrue(app.buttons["task-editor-energyLevel-high"].isSelected)
        tap("task-mode-view")
        XCTAssertTrue(app.staticTexts[title + " changed"].waitForExistence(timeout: 10))
        tap("task-editor-save")
        enabled(inboxTask(title + " changed"))
        app.terminate()
        app.launch()
        enabled(inboxTask(title + " changed"), timeout: 30)
        app.buttons[title + " changed"].tap()
        tap("task-mode-edit")
        if !app.buttons["task-editor-priority-urgent"].exists { tap("task-editor-section-organization") }
        XCTAssertTrue(app.buttons["task-editor-priority-urgent"].isSelected)
        XCTAssertTrue(app.buttons["task-editor-energyLevel-high"].isSelected)
        tap("task-editor-priority-low")
        tap("task-view-close")
        tap("task-editor-discard")
        enabled(inboxTask(title + " changed"))
        app.buttons[title + " changed"].tap()
        tap("task-mode-edit")
        if !app.buttons["task-editor-priority-urgent"].exists { tap("task-editor-section-organization") }
        XCTAssertTrue(app.buttons["task-editor-priority-urgent"].isSelected)
        tap("task-editor-priority-none")
        expectation(for: NSPredicate { _, _ in !app.buttons["task-editor-priority-urgent"].exists || !app.buttons["task-editor-priority-urgent"].isSelected }, evaluatedWith: app)
        waitForExpectations(timeout: 10)
        tap("task-editor-energyLevel-none")
        expectation(for: NSPredicate { _, _ in !app.buttons["task-editor-energyLevel-high"].exists || !app.buttons["task-editor-energyLevel-high"].isSelected }, evaluatedWith: app)
        waitForExpectations(timeout: 10)
        tap("task-editor-save")
        enabled(inboxTask(title + " changed"))
        app.terminate()
        app.launch()
        enabled(inboxTask(title + " changed"), timeout: 30)
        app.buttons[title + " changed"].tap()
        tap("task-mode-edit")
        XCTAssertFalse(app.buttons["task-editor-priority-urgent"].exists)
        XCTAssertFalse(app.buttons["task-editor-energyLevel-high"].exists)
        tap("task-view-close")
    }

